using System.Linq;

public static class ArithmeticFormula
{
    public static int ArithmeticFormula(string[] values)
    {
        return values.Count();
    }
}

solutionCode:
using System.Linq;

public static class ArithmeticFormula
{
    public static int ArithmeticFormula(string[] values)
    {
        return values.Distinct().Count();
    }
}
